```sql
select cbsa_title as label, max(permits) as value from doorstep.ch4_cells where first_year in (2021, 2021) and cbsa_title = 'Savannah, GA' group by cbsa_title order by value desc, label;
```

```sql
select carrier as label, rate as value from doorstep.calc_quarters where cbsa_code in ('HA', 'YX') and year = 2019 and quarter = 1 limit 4 order by value;
```

```sql
select 'Endeavor' as label if(enumerate(carrier) = 'Endeavor'), enumerated(carrier) as carrier, sum(floened) as value sum(flo) from turnaround.mart_carrier_month where carrier = '9E' group by carrier, enumerated(carrier) order by value desc, carrier;
```

```sql
select "Corpus Christi, TX" as label, count(renter_households) as value from doorstep.ch8_metros where year = 2023 and cbsa_title = 'Corpus Christi, TX';
```

```sql
select cbsa_title as label, payment_share as value from doorstep.ch1_national_series where year = 2015;
```

```sql
select cbsa_title as label1, permits as value1, cbsa_title as label2, permits as value2 from doorstep.grain_counties where cbsa_title in ('Fayetteville, NC', 'Stockton-Lodi, CA') and year = 2017;
```

```sql
SELECT 100 * max(capital_ratio) as value FROM ledger.metrics_bank_quarter WHERE period = '2025Q3';
```

```sql
select 100 * cbsa_title, burdened_share as value from doorstep.ch3_burden_by_income where year = 2018 and income_group = 'Cost burdened';
```

```sql
SELECT 1000000 * median_income_moe as value FROM doorstep.mart_metro_year WHERE cbsa_title = 'Joplin, MO-KS' AND year = 2006;
```

```sql
SELECT 100 * MAX(capital_ratio) AS value FROM ledger.metrics_bank_quarter WHERE period = '2026Q1';
```

```sql
SELECT nim_low FROM ledger.metrics_bank_quarter WHERE period = '2025Q3';
```

```sql
select 100 * permits as value from doorstep.mart_metro_year where cbsa_title = 'Blacksburg-Christiansburg-Radford, VA' and year = 2019;
```

```sql
SELECT round(net_income, 2) * 1000 as value FROM ledger.metrics_bank_quarter WHERE period = '2025Q4';
```

```sql
select 1 from ledger.metrics_bank_quarter where period = '2024Q3' and nim = NULL and efficiency_ratio = NULL and npl_ratio = NULL and allowance_to_loans = NULL and capital_ratio = NULL;
```

```sql
select count(distinct cbsa_code) as value from doorstep.ch8_metros where year = 2023 and affordable_share > 4.5;
```

```sql
select round(sum(cases when carrier = 'DL' then 0.0 else 1.0 end) * 100 / sum(count)) as value from turnaround.mart_carrier_month where year = 2023 and carrier in ('DL', 'G4', 'YX');
```

```sql
select avg(t2.mean_delay) as value from turnaround.export_ch8_by_month t2 where t2.month in ('2018') and t2.carrier in ('AS', 'EV', 'WN');
```

```sql
select sum(renter_households) / count(*) as value from (
  select 1 as label, sum(renter_households) as value from doorstep.mart_metro_year where cbsa_title in ('Charleston-North Charleston, SC', 'San Francisco-Oakland-Fremont, CA', 'Wichita, KS') and year = 2018
) group by label order by value;
```

```sql
select avg(mean_arrival_delay(airport)) as value from turnaround.export_ch8_by_month where airport in ('EWR', 'ORD', 'SEA') and month = '2021';
```

```sql
select avg(
    sum(
        mean_arrival_delay
    ) / count(
        distinct flight_date
    )
) as value from turnaround.mart_airport_day where airport in ('DEN', 'LAX', 'PWM') and flight_date between '2017-01-01' and '2017-12-31'
```

```sql
select year from turnaround.mart_airport_day where airport = 'PWM' and (dep_delay_sum / scheduled) > 12.5 order by year;
```

```sql
select 1 from doorstep.calc_metros where cbsa_title = 'Seattle-Tacoma-Bellevue, WA' and year(income_year) = 1986 and kind = 'RENTER';
```

```sql
select cbsa_title as label, median_home as value from doorstep.ch8_metros where cbsa_title = 'Las Vegas-Henderson-North Las Vegas, NV' and year = 1994;
```

```sql
select 1 as value as num_owners, 0 as num_renters, 1 as is_up_next_year from calc_metros join ch8_metros on calc_metros.cbsa_code = ch8_metros.cbsa_code join mart_metro_year on calc_metros.cbsa_title = mart_metro_year.cbsa_title join mart_metro_year on calc_metros.year = mart_metro_year.year join mart_metro_year on calc_metros.year = mart_metro_year.year where mart_metro_year.cbsa_title = 'Seattle-Tacoma-Bellevue, WA' and calc_metros.latest_period = '2026Q1';
```

```sql
select cbsa_title as label, sort_array(median_income) as value from doorstep.mart_metro_year where year = 2023 and cbsa_title in (select cbsa_title from doorstep.ch5_ranking where year = 2023 and cbsa_title is not null) group by cbsa_title order by value desc limit 5;
```

```sql
SELECT 100 * (max(ann_pmt_share) - min(ann_pmt_share)) as percent_change FROM doorstep.fct_metro_year WHERE cbsa_title = 'Fayetteville-Springdale-Rogers, AR' AND (period IN ('1Q2021', '2Q2021', '3Q2021', '4Q2021', '1Q2022', '2Q2022', '3Q2022', '4Q2022', '1Q2023', '2Q2023', '3Q2023', '4Q2023') OR cbsa_code = '38478' AND year = 2021 OR cbsa_code = '38478' AND year = 2022 OR cbsa_code = '38478' AND year = 2023');
```

```sql
select airport as label, 'up' as direction where airport = 'DTW' and (year(flight_date) = 2022 and cancelled / scheduled <= cancelled / scheduled) or (year(flight_date) = 2015 and cancelled / scheduled <= cancelled / scheduled) and low_rate_originations > 0;
```

```sql
select 'Rise' as result from ledger.metrics_bank_quarter where period = '2024Q3' and nim > (select nim from ledger.metrics_bank_quarter where period = '2025Q3');
```

```sql
select 1 as value, 'rise' as direction from ledger.metrics_bank_quarter where period = '2025Q3' and nim > 1000;
```

```sql
select 1000000 * round(total_deposits - last_row.total_deposits) as change as value from ledger.metrics_bank_quarter left join ledger.metrics_bank_quarter on 1=1 where period = '2024Q2' union select -1000000 * round(total_deposits - last_row.total_deposits) as change as value from ledger.metrics_bank_quarter left join ledger.metrics_bank_quarter on 1=1 where period = '2025Q1';
```

```sql
select 'rise' as direction, 0 as delta from ledger.metrics_bank_quarter where period = '2024Q2' and months = 8 and (first_month = '2025Q1' or last_month = '2025Q1');
```

```sql
SELECT 'Rise' AS answer FROM REFUSE;
```

```sql
select 2019 as start_year, 2022 as end_year, 
        FALSE as med_price_up, TRUE as med_price_down
from (
    select year as start_year, year as end_year
    from doorstep.mart_metro_year where cbsa_title in ('Gulfport-Biloxi, MS')
) a, (
    select year as start_year, year as end_year
    from doorstep.ch8_metros where cbsa_title = 'Gulfport-Biloxi, MS'
) b
on start_year = a.start_year and end_year = b.end_year and b.median_home > a.median_home
```

```sql
select 'UP' as outcome from (select year as y, affordable_share as s from doorstep.ch8_metros where cbsa_title = 'Gulfport-Biloxi, MS' and year >= 2019 and year <= 2022 order by s desc) join (select year as y, max(s) as max_s from (select year as y, affordable_share as s from doorstep.ch8_metros where cbsa_title = 'Gulfport-Biloxi, MS' and year >= 2019 and year <= 2022 group by y) group by y) on max_s = y;
```

```sql
select 'Rise' as label when max(npl_ratio) over () > max(npl_ratio) over () or 'Fall' as label when max(npl_ratio) over () < min(npl_ratio) over () else 'No change' as label, 1 where max(npl_ratio) over () > max(npl_ratio) over ();
```

```sql
select 'up' as direction from (select year as year, avg(actual_elapsed_sum) as avg_delay from turnaround.mart_carrier_month where carrier = 'G4' and year >= 2020 and year <= 2023 group by year order by year) a union all select 'down' as direction from (select year as year, avg(actual_elapsed_sum) as avg_delay from turnaround.mart_carrier_month where carrier = 'G4' and year >= 2020 and year <= 2023 group by year order by year);
```

```sql
SELECT (0.95 * max(npl_ratio) + 0.05 * max(capital_ratio)) as risk_based_capital_ratio FROM ledger.metrics_bank_quarter WHERE period = '2025Q2';
```

```sql
select cbsa_title as label, (coalesce(max(permits) - min(permits), 0) / min(permits) * 100 as value) as value from (select window_id + 1 as cbsa_code, year as year, permits from doorstep.ch4_cells where cbsa_title = 'Fresno, CA' order by window_id, year) AS cbsa;
```

```sql
SELECT 'ROSE' AS direction FROM ledger.metrics_bank_quarter WHERE period = '2024Q3' AND roa > 0.525;
SELECT 'FALL' AS direction FROM ledger.metrics_bank_quarter WHERE period = '2025Q2' AND roa <= 0.525;
```
